INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ae32ded4-a48e-4a98-8c30-83405fb323a9','9','geografie-fizica','published',0,41,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ae32ded4-a48e-4a98-8c30-83405fb323a9','ro','Pământul este turtit la poli și bombat la ecuator, formând un elipsoid de rotație. Care este cauza acestei forme?','["Mișcarea de rotație: forța centrifugă, maximă la ecuator, bombează planeta în această zonă.","Atracția Lunii trage materia spre ecuator.","Căldura din nucleu împinge scoarța spre poli.","Forma a rămas neschimbată de la formarea planetei, fără vreo cauză anume."]','Leagă forma de faptul că planeta se rotește, nu stă pe loc. Rotația generează o forță centrifugă maximă la ecuator, care bombează planeta acolo și o turtește la poli.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b7592db1-5378-4979-ba7d-4d4a4cc37fed','9','geografie-fizica','published',2,42,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b7592db1-5378-4979-ba7d-4d4a4cc37fed','ro','De ce a fost nevoie de noțiunea de geoid, pe lângă cea de elipsoid?','["Pentru că elipsoidul este mai mare decât Pământul real.","Pentru că geoidul măsoară doar adâncimea oceanelor.","Pentru că geoidul descrie mai fidel suprafața reală, luând ca reper nivelul mediu al oceanelor prelungit pe sub continente.","Pentru că elipsoidul se referă doar la atmosferă."]','Întreabă-te care formă se apropie mai mult de Pământul real, cu denivelările lui. Geoidul folosește nivelul mediu al mărilor (prelungit imaginar pe sub continente) ca suprafață de referință de 0 m, mai apropiată de realitate decât elipsoidul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8b132141-654b-4bf4-bc75-f2baf0482934','9','geografie-fizica','published',0,43,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8b132141-654b-4bf4-bc75-f2baf0482934','ro','Termenul „terroid” arată că forma reală a Pământului se abate de la figurile geometrice ideale. Care este cauza principală?','["Materia Pământului nu este omogenă fizic și chimic și nici distribuită uniform.","Pământul își schimbă forma în fiecare zi.","Oceanele acoperă cea mai mare parte a planetei.","Atmosfera apasă neuniform pe suprafață."]','Gândește-te de ce o planetă neuniformă pe dinăuntru nu poate avea o formă geometrică perfectă. Pentru că materia nu este omogenă și nu este repartizată uniform, forma reală (terroidul) se abate de la elipsoid.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('04d0e61b-8fdd-45e7-9356-149fc693b08e','9','geografie-fizica','published',3,44,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('04d0e61b-8fdd-45e7-9356-149fc693b08e','ro','Axa Pământului este înclinată constant (circa 23°27′ față de verticală). Ce consecință majoră are această înclinare, combinată cu mișcarea de revoluție?','["Producerea zilei și a nopții.","Apariția fluxului și a refluxului.","Schimbarea formei Pământului.","Succesiunea anotimpurilor."]','Gândește-te ce s-ar schimba peste an dacă axa ar fi perfect dreaptă. Înclinarea constantă face ca, pe parcursul revoluției, emisferele să primească razele solare sub unghiuri diferite — de aici succesiunea anotimpurilor. (Ziua și noaptea se datorează rotației.)');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('bc903c04-9f88-47d4-881b-9e78dcd42491','9','geografie-fizica','published',2,45,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('bc903c04-9f88-47d4-881b-9e78dcd42491','ro','Axa de rotație face un unghi de circa 23°27′ cu verticala și de circa 66°33′ cu planul orbitei. Ce relație există între cele două valori?','["Sunt egale.","Se adună și dau 180°.","Sunt complementare: împreună dau 90°.","Nu au nicio legătură între ele."]','Adună cele două unghiuri și vezi ce număr rotund obții. 23°27′ + 66°33′ = 90°, deci unghiul cu verticala și cel cu planul orbitei sunt complementare — descriu aceeași înclinare din două repere diferite.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0f7bd352-e464-4d74-bad1-ed7d3bd4babf','9','geografie-fizica','published',0,46,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0f7bd352-e464-4d74-bad1-ed7d3bd4babf','ro','Accelerația gravitațională scade dinspre poli spre Ecuator (de la 9,82 la 9,78 m/s²). Ce se întâmplă, ca urmare, cu greutatea aceluiași corp?','["Este puțin mai mică la Ecuator decât la poli.","Este mai mare la Ecuator decât la poli.","Este identică peste tot.","Devine zero la Ecuator."]','Leagă greutatea de valoarea accelerației gravitaționale din locul respectiv. Cum g este mai mic la Ecuator, același corp cântărește acolo puțin mai puțin decât la poli.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1cef159f-a9d9-475b-a5aa-ee31816ca2aa','9','geografie-fizica','published',1,47,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1cef159f-a9d9-475b-a5aa-ee31816ca2aa','ro','Forța gravitațională depinde de masele corpurilor și de distanța dintre ele. Ce s-ar întâmpla cu atracția dintre două corpuri dacă distanța dintre ele ar crește?','["Ar crește.","Ar scădea.","Ar rămâne neschimbată.","Ar deveni o forță de respingere."]','Gândește-te dacă depărtarea întărește sau slăbește atracția. Cu cât distanța dintre corpuri este mai mare, cu atât forța de atracție dintre ele este mai mică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d8329870-32e9-49e8-9d74-0c6aea13543e','9','geografie-fizica','published',2,48,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d8329870-32e9-49e8-9d74-0c6aea13543e','ro','Câmpul magnetic al Pământului are originea în forțele de convecție din nucleul extern fluid. De ce este importantă starea fluidă a acestui înveliș?','["Pentru că un strat fluid izolează termic planeta.","Pentru că fluidul oprește vântul solar.","Pentru că doar materia fluidă, în mișcare, poate genera prin curgere câmpul magnetic.","Pentru că fluidul reflectă razele solare."]','Câmpul ia naștere din mișcare — întreabă-te ce stare a materiei permite curgerea. Doar nucleul extern fluid se poate deplasa prin convecție, iar mișcarea materiei metalice (bună conducătoare) generează câmpul magnetic.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b75c4dca-a7b3-46b6-a5eb-563dc36f8826','9','geografie-fizica','published',1,49,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b75c4dca-a7b3-46b6-a5eb-563dc36f8826','ro','Aurorele polare apar mai ales în apropierea polilor. Cum se explică această localizare?','["Pentru că la poli atmosfera este cea mai groasă.","Pentru că magnetosfera dirijează vântul solar tocmai spre polii magnetici.","Pentru că Soarele răsare doar la poli.","Pentru că la poli scoarța este cea mai subțire."]','Urmărește unde „ghidează” câmpul magnetic particulele venite de la Soare. Magnetosfera canalizează vântul solar spre polii magnetici, unde particulele lui produc aurorele polare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('dc342b94-de0f-4018-9e8f-c2c1d8315e2c','9','geografie-fizica','published',3,50,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('dc342b94-de0f-4018-9e8f-c2c1d8315e2c','ro','Polii magnetici nu coincid cu polii geografici (axa lor face un unghi de circa 11,5°). Ce consecință practică are acest lucru pentru cineva care se orientează cu busola?','["Busola nu funcționează deloc.","Busola indică întotdeauna estul.","Busola arată direct spre polul geografic.","Acul busolei indică nordul magnetic, ușor diferit de nordul geografic."]','Gândește-te spre ce „nord” se aliniază de fapt acul magnetizat. Acul busolei se orientează după câmpul magnetic, deci arată nordul magnetic, care diferă puțin de nordul geografic.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c96d5aef-498f-4e2e-a3df-8020e2aed87c','9','geografie-fizica','published',1,51,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c96d5aef-498f-4e2e-a3df-8020e2aed87c','ro','Magnetosfera deviază vântul solar (fluxul de particule încărcate venit de la Soare). Ce rol important îndeplinește astfel pentru planetă?','["Mărește temperatura la suprafață.","Ecranează planeta, abătând o mare parte din particulele dăunătoare ale vântului solar.","Produce mareele oceanice.","Determină forma elipsoidală a Pământului."]','Dacă magnetosfera „abate” vântul solar, gândește-te de ce ferește ea suprafața. Acționând ca un scut, magnetosfera deviază particulele încărcate ale vântului solar, protejând planeta de efectele lor dăunătoare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8d5b1d09-969e-4aab-9eac-7ee0ce238893','9','geografie-fizica','published',2,52,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8d5b1d09-969e-4aab-9eac-7ee0ce238893','ro','Treapta geotermică în litosferă este de circa 33 m pentru fiecare 1°C. Aproximativ cu cât crește temperatura dacă cobori 330 m?','["Cu circa 1°C.","Cu circa 33°C.","Cu circa 10°C.","Cu circa 100°C."]','Împarte adâncimea coborâtă la treapta geotermică pentru a afla câți „pași” de 1°C faci. 330 m ÷ 33 m ≈ 10, deci temperatura crește cu aproximativ 10°C.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('51bae39a-0b01-4bd9-aa75-aea3bdbf023c','9','geografie-fizica','published',0,53,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('51bae39a-0b01-4bd9-aa75-aea3bdbf023c','ro','Circa 90% din căldura internă provine din radioactivitate, iar restul de circa 10% este căldură reziduală. Ce concluzie corectă tragem?','["Principala sursă a căldurii interne actuale este dezintegrarea radioactivă, nu căldura rămasă de la formare.","Pământul s-a răcit deja complet.","Toată căldura provine de la Soare.","Căldura reziduală este sursa principală."]','Compară cele două procente și vezi care „cântărește” mai mult. Cu 90% din total, dezintegrarea radioactivă (a unor izotopi de uraniu și potasiu) este sursa dominantă a căldurii interne, nu căldura reziduală.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0f1cf5e6-af39-4013-8254-6d903fd2d1f6','9','geografie-fizica','published',1,54,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0f1cf5e6-af39-4013-8254-6d903fd2d1f6','ro','Nucleul intern este cel mai fierbinte strat, totuși este solid, în timp ce nucleul extern, mai puțin adânc, este fluid. Cum se explică acest aparent paradox?','["Pentru că nucleul intern este de fapt mai rece.","Pentru că presiunea uriașă din centrul Pământului menține nucleul intern în stare solidă, în ciuda temperaturii.","Pentru că nucleul intern nu conține metale.","Pentru că în centru nu ajunge deloc căldură."]','Pe lângă temperatură, mai există un factor care „strânge” materia în adâncime — care? Presiunea extrem de mare din centru ține nucleul intern solid, deși temperatura de acolo este cea mai ridicată.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ee6a6600-333c-4e2d-b1a4-ed6507967c06','9','geografie-fizica','published',3,55,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ee6a6600-333c-4e2d-b1a4-ed6507967c06','ro','Astenosfera (partea superioară a mantalei) are un comportament plastic, aproape fluid. De ce este importantă această proprietate?','["Pentru că reflectă razele solare.","Pentru că oprește căldura internă.","Pentru că determină forma elipsoidală a planetei.","Pentru că pe ea se sprijină și se deplasează plăcile litosferice."]','Gândește-te ce permite un strat plastic, spre deosebire de unul rigid: mișcarea a ceea ce se află deasupra. Fiind plastică, astenosfera permite alunecarea și deplasarea plăcilor litosferice de deasupra ei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6fdcbb30-1981-4a19-89f3-b224442f7043','9','geografie-fizica','published',0,56,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6fdcbb30-1981-4a19-89f3-b224442f7043','ro','Scoarța are 80–100 km grosime sub continente, dar doar 10–20 km sub oceane. Ce poți deduce comparând cele două valori?','["Scoarța de sub oceane este mult mai subțire decât cea de sub continente.","Scoarța are aceeași grosime peste tot.","Sub oceane nu există scoarță.","Scoarța continentală este cea mai subțire."]','Compară direct cele două intervale de grosime. Valorile arată că scoarța de sub oceane (10–20 km) este mult mai subțire decât cea de sub continente (80–100 km).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('851a2d4c-2067-4f5e-bee1-d554bc323ca4','9','geografie-fizica','published',2,57,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('851a2d4c-2067-4f5e-bee1-d554bc323ca4','ro','Densitatea medie a Pământului este de circa 5,52 g/cm³, iar rocile de la suprafață au în jur de 2,7 g/cm³. Ce deducem despre interiorul planetei?','["Că interiorul este gol.","Că rocile de la suprafață sunt cele mai dense.","Că interiorul (mai ales nucleul) este alcătuit din materie mult mai densă decât rocile de la suprafață.","Că densitatea este aceeași peste tot."]','Dacă media este mult mai mare decât valoarea de la suprafață, unde trebuie „ascunsă” materia grea? Pentru ca media să ajungă la 5,52 g/cm³, interiorul — în special nucleul metalic — trebuie să fie mult mai dens decât scoarța.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('284ac07f-2b77-4483-96cc-0cb2a0d2507e','9','geografie-fizica','published',1,58,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('284ac07f-2b77-4483-96cc-0cb2a0d2507e','ro','Învelișurile chimice ale Pământului poartă nume precum Sial, Sima sau Nife, formate din simbolurile elementelor dominante. Ce elemente predomină în nucleul intern (Nife)?','["Siliciu și aluminiu.","Nichel și fier.","Oxigen și siliciu.","Calciu și sodiu."]','Desparte denumirea „Nife” în simbolurile chimice ascunse în ea. „Ni” + „Fe” = nichel și fier, elementele dominante ale nucleului intern.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('60c226eb-2cf8-4671-ace7-105f891c2173','9','geografie-fizica','published',3,59,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('60c226eb-2cf8-4671-ace7-105f891c2173','ro','Cel mai răspândit element din alcătuirea Pământului este oxigenul (circa 47%), deși îl știm mai ales ca gaz din aer. Cum se explică abundența lui în „corpul” solid al planetei?','["Tot oxigenul planetei se află în atmosferă.","Oxigenul provine exclusiv de la Soare.","Oxigenul formează nucleul planetei.","Cea mai mare parte a oxigenului este legată chimic în minerale (oxizi și silicați), nu liberă în aer."]','Gândește-te că un element poate fi „prins” în roci, nu doar liber în aer. Oxigenul din scoarță este combinat chimic în oxizi și silicați, de aceea este atât de abundent în partea solidă a planetei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ee1264f5-533f-4b73-b4e0-ad785a5ff5cd','9','geografie-fizica','published',0,60,1783000000000,1783000000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ee1264f5-533f-4b73-b4e0-ad785a5ff5cd','ro','Oxigenul (47%) și siliciul (28%) însumează aproape 75% din alcătuirea Pământului. Ce tip de minerale ne așteptăm să predomine în scoarță?','["Silicații (minerale formate mai ales din siliciu și oxigen).","Metalele native (aur, cupru).","Sările de sodiu.","Mineralele de fier pur."]','Combină cele două elemente cele mai abundente și gândește-te ce minerale formează împreună. Siliciul și oxigenul, fiind dominante, formează silicații — grupa de minerale cea mai răspândită în scoarță.');
